  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= len(s) <= 200000",
      "description": "The length of the string s is between 1 and 200,000 characters."
    },
    {
      "id": "P2",
      "expression": "1 <= q <= 200000",
      "description": "The number of queries is between 1 and 200,000."
    },
    {
      "id": "P3",
      "expression": "1 <= l_i <= r_i <= len(s)",
      "description": "Each query range is within the bounds of the string s."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output[i] == sum(z_i for z_i in z_function(s[l_i-1:r_i]))",
      "description": "The output for each query corresponds to the Ж-function of the substring s[l_i-1:r_i]."
    }
  ],
  "invariants": []
}
